    required this.limit,
    required this.ruleVersion,
    required this.totalEvents,
    required this.truncated,
  });
  final List<StateEvent> events;
  final int limit;
  final String ruleVersion;
  final int totalEvents;
  final bool truncated;
  factory StateEvents.fromJson(Map<String, dynamic> json) {
    if (!json.containsKey('events')) {
      throw const FormatException('Missing required field: events');
    }
    if (!json.containsKey('total_events')) {
      throw const FormatException('Missing required field: total_events');
    }
    if (!json.containsKey('truncated')) {
      throw const FormatException('Missing required field: truncated');
    }
    return StateEvents(
      events: decodeField<List<dynamic>>(json['events'])
          .map((item) => StateEvent.fromJson(object(item)))
          .toList(),
      limit: decodeField<int>(
        (json.containsKey('limit') ? json['limit'] : 1000),
      ),
      ruleVersion: decodeField<String>(
        (json.containsKey('rule_version')
            ? json['rule_version']
            : "raw-transitions-v1"),
      ),
      totalEvents: decodeField<int>(json['total_events']),
      truncated: decodeField<bool>(json['truncated']),
    );
  }
}

